<?php require_once __DIR__.'/includes/db.php'; $code=trim($_GET['kode']??''); $q=$pdo->prepare('SELECT p.*, dp.jumlah, dp.harga_satuan, dp.subtotal, kt.nama_kategori, m.tim_tuan_rumah, m.tim_tamu, m.tanggal, m.stadion FROM pemesanan p JOIN detail_pemesanan dp ON dp.pemesanan_id=p.id JOIN kategori_tiket kt ON kt.id=dp.kategori_tiket_id JOIN pertandingan m ON m.id=dp.pertandingan_id WHERE p.kode_pemesanan=?'); $q->execute([$code]); $booking=$q->fetch(); ?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Pemesanan | LagaKita</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/style.css" rel="stylesheet"></head><body><?php include __DIR__.'/includes/navbar.php'; ?><main class="container py-5"><div class="row justify-content-center"><div class="col-lg-7"><?php if(!$booking): ?><h1>Data pemesanan tidak ditemukan</h1><a href="pertandingan.php">Lihat pertandingan</a><?php else: ?><div class="card match-card"><div class="card-body p-5 text-center"><div class="display-5 mb-3">✓</div><p class="eyebrow">PEMESANAN TERCATAT</p><h1 class="h2 fw-bold">Terima kasih!</h1><p class="text-muted">Simpan kode pemesanan ini untuk referensi.</p><div class="alert alert-success fs-4 fw-bold"><?= e($booking['kode_pemesanan']) ?></div><div class="text-start"><p><strong>Pertandingan:</strong> <?= e($booking['tim_tuan_rumah']) ?> vs <?= e($booking['tim_tamu']) ?></p><p><strong>Tiket:</strong> <?= e($booking['nama_kategori']) ?> × <?= (int)$booking['jumlah'] ?></p><p><strong>Total:</strong> <?= rupiah($booking['total_harga']) ?></p><p><strong>Status:</strong> <?= e($booking['status']) ?></p><p class="small text-muted mb-0">Ini starter project. Pembayaran dan pengiriman tiket belum diintegrasikan.</p></div><a href="index.php" class="btn btn-success mt-4">Kembali ke beranda</a></div></div><?php endif; ?></div></div></main><?php include __DIR__.'/includes/footer.php'; ?></body></html>
